<script setup lang="ts">
import { computed, ref } from 'vue'
type Transaction = { id: string; title: string; category: string; type: '收入' | '支出'; amount: number; date: string }
const storageKey = 'ikaros-console-finance-transactions'; const read = (): Transaction[] => { try { const value = JSON.parse(localStorage.getItem(storageKey) || '[]'); return Array.isArray(value) ? value : [] } catch { return [] } }
const transactions = ref<Transaction[]>(read().length ? read() : [{ id: 'demo-1', title: '工资收入', category: '薪资', type: '收入', amount: 12000, date: '今天' }, { id: 'demo-2', title: '云存储订阅', category: '软件服务', type: '支出', amount: 68, date: '昨天' }]); const query = ref(''); const filter = ref('全部'); const dialog = ref(false); const title = ref(''); const category = ref(''); const type = ref<'收入' | '支出'>('支出'); const amount = ref(0); const toast = ref('')
const visible = computed(() => transactions.value.filter(item => (filter.value === '全部' || item.type === filter.value) && `${item.title} ${item.category}`.toLowerCase().includes(query.value.toLowerCase()))); const income = computed(() => transactions.value.filter(item => item.type === '收入').reduce((sum, item) => sum + item.amount, 0)); const expense = computed(() => transactions.value.filter(item => item.type === '支出').reduce((sum, item) => sum + item.amount, 0)); const balance = computed(() => income.value - expense.value)
function notify(message: string) { toast.value = message; window.setTimeout(() => toast.value = '', 2400) }
function save() { localStorage.setItem(storageKey, JSON.stringify(transactions.value)) }
function create() { if (!title.value.trim() || !category.value.trim() || amount.value <= 0) { notify('请填写名称、分类和正数金额'); return } transactions.value.unshift({ id: `local-${Date.now()}`, title: title.value.trim(), category: category.value.trim(), type: type.value, amount: Number(amount.value), date: '刚刚' }); save(); dialog.value = false; title.value = ''; category.value = ''; amount.value = 0; notify('交易已保存到本地账本') }
</script>
<template><div class="finance-shell"><header class="catalog-topbar"><div class="catalog-brand"><span class="brand-mark">i</span><strong>Ikaros <small>Console</small></strong></div><span class="catalog-context">个人记账 · 本地账本</span><span class="mini-avatar">陈</span></header><main class="catalog-main finance-main"><div class="catalog-heading"><div><p class="eyebrow">个人记账</p><h1>账本总览</h1><p>本页数据仅保存在当前浏览器；Finance 数据不会上传或伪装成已同步状态。</p></div><button class="filled-button" @click="dialog = true">＋ 新建交易</button></div><nav class="finance-tabs"><RouterLink to="/console/finance" class="active">总览</RouterLink><RouterLink to="/console/finance/accounts">账户</RouterLink><RouterLink to="/console/finance/transactions">交易</RouterLink><RouterLink to="/console/finance/budgets">预算</RouterLink><RouterLink to="/console/finance/reconcile">对账与导入</RouterLink></nav><section class="finance-summary"><article class="surface-card"><span>账本余额</span><strong>¥ {{ balance.toFixed(2) }}</strong><small>收入减支出</small></article><article class="surface-card"><span>收入</span><strong class="finance-income">¥ {{ income.toFixed(2) }}</strong><small>当前本地账本</small></article><article class="surface-card"><span>支出</span><strong class="finance-expense">¥ {{ expense.toFixed(2) }}</strong><small>当前本地账本</small></article></section><div class="finance-toolbar surface-card"><div class="search-inline"><span>⌕</span><input v-model="query" placeholder="搜索交易或分类" /></div><div class="filter-row"><button v-for="value in ['全部','收入','支出']" :key="value" class="filter-chip" :class="{ active: filter === value }" @click="filter = value">{{ value }}</button></div></div><section class="finance-table surface-card"><table><thead><tr><th>交易</th><th>分类</th><th>类型</th><th>金额</th><th>日期</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td><b>{{ item.title }}</b></td><td>{{ item.category }}</td><td><span class="status-chip" :class="item.type === '收入' ? 'success' : 'warning'">● {{ item.type }}</span></td><td :class="item.type === '收入' ? 'finance-income' : 'finance-expense'">{{ item.type === '收入' ? '+' : '−' }} ¥ {{ item.amount.toFixed(2) }}</td><td class="muted-text">{{ item.date }}</td></tr><tr v-if="visible.length === 0"><td colspan="5" class="no-results">没有匹配交易<button class="text-button" @click="query = ''; filter = '全部'">清除筛选</button></td></tr></tbody></table></section></main><div v-if="dialog" class="role-create-scrim" @click.self="dialog = false"><section class="role-create-dialog"><div class="dialog-title"><div><p class="eyebrow">个人记账</p><h2>新建交易</h2></div><button class="icon-button" @click="dialog = false">×</button></div><label>名称 *<input v-model="title" maxlength="160" placeholder="例如：午餐" @keyup.enter="create" /></label><label>分类 *<input v-model="category" maxlength="80" placeholder="例如：餐饮" /></label><label>类型 *<select v-model="type"><option value="支出">支出</option><option value="收入">收入</option></select></label><label>金额 *<input v-model.number="amount" type="number" min="0.01" step="0.01" placeholder="0.00" /></label><p class="account-note">创建后仅写入当前浏览器本地账本；导入/同步和服务端财务 API 尚未启用。</p><div class="dialog-actions"><button class="outlined-button" @click="dialog = false">取消</button><button class="filled-button" @click="create">保存交易</button></div></section></div><div v-if="toast" class="snackbar">✓ {{ toast }}<button @click="toast = ''">×</button></div></div></template>
